// Lógica do nó "Decidir lembretes" do fluxo "eLabFTW – Lembrete de caderno parado".
// Função pura: recebe as fichas completas, os experimentos, os usuários e o registro de lembretes;
// devolve um item por ficha a lembrar (com o pedido de e-mail para o subfluxo) e o registro a guardar.

const DIA = 24 * 3600e3;

function dataDe(s) {
  if (!s) return null;
  const d = new Date(String(s).length <= 10 ? `${s}T12:00:00` : String(s).replace(' ', 'T'));
  return Number.isNaN(d.getTime()) ? null : d;
}

function fmt(d) {
  return d.toISOString().slice(0, 10).split('-').reverse().join('/');
}

function camposDaFicha(ficha) {
  let m = ficha.metadata_decoded || ficha.metadata;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (e) { m = {}; }
  }
  return (m && m.extra_fields) || {};
}

function decidirLembretes({ fichas, experimentos, usuarios, registros, hoje, cfg }) {
  const criadoEm = new Map(experimentos.filter((e) => e && e.id !== undefined).map((e) => [String(e.id), e.created_at]));
  const usuario = new Map(usuarios.filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const reg = new Map(registros.filter((r) => r && r.ficha_id !== undefined && r.ficha_id !== null).map((r) => [String(r.ficha_id), r]));
  const testador = usuario.get(String(cfg.usuarioTesteId));
  const saida = [];

  for (const f of fichas) {
    if (!f || f.id === undefined) continue;
    if (f.category_title !== cfg.categoriaFicha || f.status_title !== cfg.situacaoAtiva) continue;

    const campos = camposDaFicha(f);
    const prazoCampo = Number(campos[cfg.campoPrazo] && campos[cfg.campoPrazo].value);
    const prazo = Number.isFinite(prazoCampo) && prazoCampo >= 1 ? Math.floor(prazoCampo) : cfg.prazoPadrao;

    const entradas = (f.related_experiments_links || [])
      .filter((l) => l && l.category_title === cfg.categoriaCaderno)
      .map((l) => dataDe(criadoEm.get(String(l.entityid))))
      .filter(Boolean);
    const ultimaEntrada = entradas.length ? new Date(Math.max(...entradas.map((d) => d.getTime()))) : null;
    const referencia = ultimaEntrada
      || dataDe(campos['Início'] && campos['Início'].value)
      || dataDe(f.created_at);
    if (!referencia) continue;

    const dias = Math.floor((hoje - referencia) / DIA);
    if (dias < prazo) continue;

    const anterior = reg.get(String(f.id));
    const refIso = referencia.toISOString();
    if (anterior && anterior.referencia === refIso && anterior.ultimo_lembrete
      && hoje - new Date(anterior.ultimo_lembrete) < cfg.repetirDias * DIA) continue;

    const lider = usuario.get(String(f.userid));
    const real = lider && lider.email ? lider.email : '';
    if (cfg.modoTeste && !(testador && testador.email)) {
      throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi enviado.`);
    }
    const para = cfg.modoTeste ? testador.email : real;
    const registro = { ficha_id: Number(f.id), projeto: String(f.title ?? ''), referencia: refIso, ultimo_lembrete: hoje.toISOString() };
    if (!para) {
      saida.push({ acao: 'sem-destinatario', ...registro });
      continue;
    }

    const nomeLider = (lider && lider.fullname) || f.fullname || 'pesquisador(a)';
    const blocos = [
      { tipo: 'paragrafo', texto: `Olá, ${nomeLider}.` },
      { tipo: 'paragrafo', texto: `O caderno do projeto "${f.title}" está há ${dias} dias sem entrada nova. O prazo combinado para este projeto é de ${prazo} dias.` },
      { tipo: 'campos', itens: [
        { rotulo: 'Projeto', valor: f.title },
        { rotulo: 'Última entrada de caderno', valor: ultimaEntrada ? fmt(ultimaEntrada) : 'nenhuma ligada à ficha' },
        { rotulo: 'Contando desde', valor: fmt(referencia) },
        { rotulo: 'Prazo do projeto', valor: `${prazo} dias` },
      ] },
      { tipo: 'paragrafo', texto: 'Registre o que aconteceu desde então: decisões, avaliações, falhas e surpresas (Diretrizes, A.3). Lembre-se de ligar a entrada à ficha do projeto; entradas sem ligação não contam.' },
    ];
    if (cfg.modoTeste) blocos.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este lembrete iria para ${nomeLider}${real ? ` (${real})` : ' (sem e-mail)'}.` });

    saida.push({
      acao: 'lembrar',
      ...registro,
      para,
      nomeRemetente: 'PD&I Modal',
      responderPara: 'pesquisa@modal.org.br',
      assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}eLabFTW: caderno do projeto "${f.title}" parado há ${dias} dias`,
      etiqueta: 'eLabFTW · Caderno de pesquisa',
      titulo: `O caderno de "${f.title}" está parado há ${dias} dias`,
      blocos,
      acaoRotulo: 'Abrir a ficha do projeto',
      acaoUrl: `${cfg.urlPublica}/database.php?mode=view&id=${f.id}`,
      rodape: `Lembrete automático do eLabFTW do Modal; repete a cada ${cfg.repetirDias} dias enquanto o caderno estiver parado. O prazo fica no campo "${cfg.campoPrazo}" da ficha. Dúvidas: pesquisa@modal.org.br.`,
    });
  }
  return saida;
}


const dados = (nome) => $(nome).all().map((i) => i.json);
const saida = decidirLembretes({
  fichas: dados('Ler ficha completa'),
  experimentos: dados('Ler experimentos').filter((o) => o && o.id !== undefined),
  usuarios: dados('Ler usuários'),
  registros: dados('Ler lembretes anteriores'),
  hoje: new Date(),
  cfg: $('Configuração').first().json,
});
return saida.map((json) => ({ json }));

